try-try-except-basics-sketch2.solutionCode:
first = input().strip()
second = input().strip()

for filename in [first, second]:
    path = "data/" + filename
    try:
        with open(path, "r") as file:
            text = file.read().strip()
        print(text)
    except FileNotFoundError:
        print("Missing: " + filename)

